#include <vector>
#include <cmath>
std::vector<long long> vwapSchedule(long long Q, const std::vector<double>& w){
    int n = w.size();
    std::vector<long long> out(n, 0);
    double tot = 0; for (double x : w) tot += x;
    if (tot <= 0){ for (int i=0;i<n;i++) out[i] = Q / n; out[n-1] += Q - (Q/n)*n; return out; }
    long long assigned = 0; int lastNZ = 0;
    for (int i = 0; i < n; i++){
        out[i] = (long long)std::llround(Q * (w[i] / tot));
        assigned += out[i];
        if (w[i] > 0) lastNZ = i;
    }
    out[lastNZ] += Q - assigned;   // absorb rounding remainder
    return out;
}
